import { readFileSync, mkdirSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { createHash } from 'node:crypto';
import { Ajv2020 } from 'ajv/dist/2020.js';
import standalone from 'ajv/dist/standalone/index.js';

const root = new URL('../', import.meta.url);
const read = (p) => readFileSync(new URL(p, root), 'utf8');
const nodes = JSON.parse(read('docs/source-plan/v2/node-catalog.json'));
const schema = JSON.parse(read('docs/source-plan/v2/schemas/workflow.schema.json'));
const output = {
  'node-registry.ts':
    '// Generated by tools/generate-contracts.mjs; edit the source registry, then regenerate.\nexport const NODE_DEFINITIONS = ' +
    JSON.stringify(
      nodes.map((n) => ({
        type: n.type,
        label: n.label,
        group: n.group,
        ports: n.productionPorts,
        requiredPorts: n.requiredPorts,
        runtime: n.runtime,
        configFields: n.configFields,
      })),
      null,
      2,
    ) +
    ' as const;\nexport type NodeType = typeof NODE_DEFINITIONS[number]["type"];\n',
  'workflow-schema.ts':
    '// Generated workflow wire schema; semantic validation is a separate gate.\nexport const workflowSchema = ' +
    JSON.stringify(schema, null, 2) +
    ' as const;\n',
};
const configs = Object.fromEntries(
  schema.$defs.node.allOf.map((c) => [
    c.if.properties.type.const,
    c.then.properties.config.properties,
  ]),
);
output['node-registry.ts'] +=
  'export const NODE_CONFIG_SCHEMAS: Readonly<Record<NodeType, Readonly<Record<string, { type?: string; [key: string]: unknown }>>>> = ' +
  JSON.stringify(configs, null, 2) +
  ';\n';
const compiler = new Ajv2020({
  allErrors: true,
  strict: true,
  strictRequired: false,
  code: { source: true, esm: true, lines: true },
});
compiler.addSchema(schema);
let validator = standalone(compiler, { validateWorkflow: schema.$id });
const imports = new Map();
validator = validator.replace(
  /require\("([^"]+)"\)(\.default)?/g,
  (_match, module, defaultMember) => {
    if (!module.startsWith('ajv/dist/runtime/'))
      throw new Error('Unexpected standalone runtime dependency: ' + module);
    const name = imports.get(module) ?? 'runtime' + imports.size;
    imports.set(module, name);
    return defaultMember
      ? '(' + name + '.default?.default ?? ' + name + '.default)'
      : '(' + name + '.default ?? ' + name + ')';
  },
);
output['workflow-validator.js'] =
  '// Generated standalone validation: no runtime eval/new Function.\n' +
  [...imports]
    .map(
      ([module, name]) => 'import * as ' + name + ' from ' + JSON.stringify(module + '.js') + ';\n',
    )
    .join('') +
  validator.trimEnd() +
  '\n';
output['workflow-validator.d.ts'] =
  '// Generated validation signature.\nimport type { WorkflowBundle } from "../types.js";\nexport declare const validateWorkflow: { (data: unknown): data is WorkflowBundle; errors?: readonly { instancePath: string; message?: string }[] | null };\n';
for (const [name, text] of Object.entries(output)) {
  const path = new URL('packages/contracts/src/generated/' + name, root);
  if (process.argv.includes('--check')) {
    if (readFileSync(path, 'utf8') !== text)
      throw new Error('Generated contract is stale: ' + name);
  } else {
    mkdirSync(fileURLToPath(new URL('packages/contracts/src/generated/', root)), {
      recursive: true,
    });
    writeFileSync(path, text);
  }
}
console.log(
  'Contract schema and ' +
    nodes.length +
    ' nodes verified; schema SHA256 ' +
    createHash('sha256').update(JSON.stringify(schema)).digest('hex'),
);
